import pandas as pd
import matplotlib.pyplot as plt
import numpy as np
import os
import matplotlib.ticker as ticker

def plot_two_graphs(csv_filename):
    # 1. Verify file exists
    if not os.path.exists(csv_filename):
        print(f"Error: Could not find '{csv_filename}'. Make sure your C++ code has created it!")
        return

    # 2. Read the CSV file generated by C++
    df = pd.read_csv(csv_filename)

    x_col = df.columns[0]      # Input_Size
    methods = df.columns[1:]   # Retrieving the Data Headers 

    # Make sure we have at least 4 methods
    if len(methods) < 4:
        print("Error: Expected at least 4 data columns in CSV.")
        return

    # 3. Create a figure with 2 side-by-side subplots (1 row, 2 columns)
    fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(14, 6))

    # Calculate X-ticks: 50, 100, 150... up to max X
    max_x = int(df[x_col].max())
    x_ticks = np.arange(50, max_x + 1, 50)

    # --- GRAPH 1: Methods 1 & 2 ---
    ax1.plot(df[x_col], df[methods[0]], label=methods[0], color='tab:blue', linewidth=2)
    ax1.plot(df[x_col], df[methods[1]], label=methods[1], color='tab:orange', linewidth=2)
    
    ax1.set_title("Gauss Filter", fontsize=12, fontweight='bold')
    ax1.set_xlabel("Number of Images/Input (N)")
    ax1.set_ylabel("Time Taken (ms)")
    ax1.set_xticks(x_ticks)
    ax1.grid(True, linestyle='--', alpha=0.6)
    ax1.legend()

    # --- GRAPH 2: Methods 3 & 4 ---
    ax2.plot(df[x_col], df[methods[2]], label=methods[2], color='tab:green', linewidth=2)
    ax2.plot(df[x_col], df[methods[3]], label=methods[3], color='tab:red', linewidth=2)
    
    # Set Y-axis label formatter: multiply tick values by 0.001
    ax2.yaxis.set_major_formatter(ticker.FuncFormatter(lambda y, _: f"{y*0.001:.1f}"))    
    
    ax2.set_title("Median Filter", fontsize=12, fontweight='bold')
    ax2.set_xlabel("Number of Images/Input (N)")
    ax2.set_ylabel("Time Taken (s)")
    ax2.set_xticks(x_ticks)
    ax2.grid(True, linestyle='--', alpha=0.6)
    ax2.legend()

    # 4. Adjust layout to avoid overlapping labels
    plt.tight_layout()

    # 5. Save image and display
    output_image = "benchmarks.png"
    plt.savefig(output_image, dpi=300)
    print(f"Saved graph as '{output_image}'. Displaying plot...")
    plt.show()

if __name__ == "__main__":
    plot_two_graphs("benchmark_results.csv")
